.version 9.4
.target sm_89
.address_size 64
.visible .entry cache_invalidation(.param .u64 flag, .param .u64 out) {
.reg .pred %p<3>;
.reg .b32 %r<10>;
.reg .b64 %rd<5>;
ld.param.u64 %rd0, [flag];
ld.param.u64 %rd1, [out];
add.u64 %rd2, %rd0, 256;
add.u64 %rd3, %rd0, 128;
mov.u32 %r0, %tid.x;
mov.u32 %r7, %ctaid.x;
mov.u32 %r8, %ntid.x;
mad.lo.u32 %r6, %r7, %r8, %r0;
mov.u32 %r9, %nctaid.x;
add.u32 %r9, %r9, -1;
mul.lo.u32 %r9, %r9, %r8;
mov.u32 %r1, 0;
mov.u32 %r4, 0;
setp.eq.u32 %p0, %r7, 0;
@%p0 bra producer;
ld.global.ca.u32 %r1, [%rd2];
add.u32 %r9, %r1, 1;
atom.global.add.u32 %r5, [%rd3], %r9;
loop:
add.u32 %r4, %r4, 1;
ld.acquire.gpu.global.u32 %r2, [%rd0];
setp.ne.u32 %p1, %r2, 0;
@%p1 bra consumer_done;
setp.lt.u32 %p2, %r4, 16384;
@%p2 bra loop;
consumer_done:
ld.global.ca.u32 %r3, [%rd2];
bra done;
producer:
add.u32 %r4, %r4, 1;
ld.relaxed.gpu.global.u32 %r2, [%rd3];
setp.ge.u32 %p1, %r2, %r9;
@%p1 bra producer_done;
setp.lt.u32 %p2, %r4, 16384;
@%p2 bra producer;
producer_done:
mov.u32 %r3, 42;
st.global.u32 [%rd2], %r3;
mov.u32 %r5, 1;
st.release.gpu.global.u32 [%rd0], %r5;
done:
mul.wide.u32 %rd4, %r6, 16;
add.u64 %rd1, %rd1, %rd4;
st.global.v4.u32 [%rd1], {%r1, %r3, %r2, %r4};
ret;
}
